const sigmaRed = Color(0xFFC82828), sigmaNavy = Color(0xFF172033), sigmaPale = Color(0xFFF6F8FC), sigmaBlue = Color(0xFFE8F0FF), sigmaGreen = Color(0xFF078443), sigmaOrange = Color(0xFFF97316);

