class SigmaChip extends StatelessWidget { const SigmaChip({super.key, required this.text, this.color = sigmaGreen}); final String text; final Color color; @override Widget build(BuildContext c) => Container(padding: const EdgeInsets.symmetric(horizontal: 10,vertical: 5), decoration: BoxDecoration(color: color.withValues(alpha: .13),borderRadius: BorderRadius.circular(20)), child: Text(text, style: TextStyle(fontSize: 11,fontWeight: FontWeight.w800,color: color))); }
class SigmaButton extends StatelessWidget { const SigmaButton({super.key, required this.label, required this.onPressed, this.icon, this.secondary = false, this.color}); final String label; final VoidCallback onPressed; final IconData? icon; final bool secondary; final Color? color; @override Widget build(BuildContext c) => SizedBox(height: 52, child: FilledButton.icon(onPressed:onPressed, icon: icon == null ? const SizedBox.shrink() : Icon(icon), label:Text(label), style:FilledButton.styleFrom(backgroundColor: secondary ? sigmaBlue : color ?? sigmaRed, foregroundColor: secondary ? sigmaNavy : Colors.white, shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(10)), textStyle:const TextStyle(fontWeight:FontWeight.w800)))); }
class SigmaHeader extends StatelessWidget { const SigmaHeader({super.key, required this.title, this.subtitle, this.back = false, this.onBack, this.online = true}); final String title; final String? subtitle; final bool back, online; final VoidCallback? onBack; @override Widget build(BuildContext c) => Row(children:[if(back) IconButton(onPressed:onBack ?? ()=>Navigator.pop(c),icon:const Icon(Icons.arrow_back)) else ClipRRect(borderRadius:BorderRadius.circular(9),child:Image.asset('assets/images/logo.jpeg',width:39,height:39,fit:BoxFit.cover)), const SizedBox(width:10), Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(back ? title : 'SIGMA',style:TextStyle(fontWeight:FontWeight.w900,fontSize: back?20:14,color:back?sigmaNavy:sigmaRed)),Text(back ? subtitle ?? '' : title,style:TextStyle(fontWeight:FontWeight.w800,fontSize:back?12:20,color:sigmaNavy))])), SigmaChip(text:online?'● ONLINE':'● OFFLINE',color:online?sigmaGreen:sigmaOrange), const SizedBox(width:8), if(!back) const CircleAvatar(radius:18,backgroundColor:sigmaRed,foregroundColor:Colors.white,child:Icon(Icons.person_outline))]); }
