class MockMap extends StatelessWidget { const MockMap({super.key, this.height = 250, this.route = false, this.onTap}); final double height; final bool route; final VoidCallback? onTap; @override Widget build(BuildContext c)=>InkWell(onTap:onTap,child:Container(height:height,decoration:BoxDecoration(color:const Color(0xFFD9F5E4),borderRadius:BorderRadius.circular(16)),child:Stack(children:[Positioned.fill(child:CustomPaint(painter:_MapPainter(route))), const Positioned(top:14,left:14,child:SigmaChip(text:'GPS Akurat ±3m')), Positioned(right:24,top:70,child:CircleAvatar(backgroundColor:sigmaRed,foregroundColor:Colors.white,child:Icon(Icons.local_fire_department))), Positioned(left:45,bottom:35,child:CircleAvatar(backgroundColor:sigmaGreen,foregroundColor:Colors.white,child:Icon(Icons.person_pin_circle))), const Positioned(right:12,bottom:12,child:Column(children:[CircleAvatar(child:Icon(Icons.add)),SizedBox(height:6),CircleAvatar(child:Icon(Icons.remove))]))]))); }
class _MapPainter extends CustomPainter { const _MapPainter(this.route); final bool route; @override void paint(Canvas c,Size s){final p=Paint()..color=const Color(0x8860A5FA)..strokeWidth=5..style=PaintingStyle.stroke; c.drawLine(Offset(0,s.height*.7),Offset(s.width,s.height*.35),p); if(route){p..color=sigmaOrange..strokeWidth=7; final path=Path()..moveTo(s.width*.2,s.height*.85)..lineTo(s.width*.48,s.height*.55)..lineTo(s.width*.74,s.height*.2); c.drawPath(path,p);} else {p..color=const Color(0xAAE54646)..strokeWidth=4; c.drawCircle(Offset(s.width*.67,s.height*.35),42,p);}} @override bool shouldRepaint(_MapPainter old)=>old.route!=route; }
